-- 1. INSERT программы с промптами, лендингом, hub_messages
INSERT INTO programs (
  slug, title, description,
  system_prompt, author_chat_system_prompt, anonymous_system_prompt,
  free_chat_welcome, author_chat_welcome,
  anonymous_quick_replies,
